import sys

def main():
    data = sys.stdin.read().split()
    rates = data[0]
    q = int(data[1])
    best = {}
    for entry in rates.split(','):
        a, b, m, c = entry.split(':')
        key = (int(c), m)
        d = best.setdefault(a, {})
        if b not in d or key < d[b]:
            d[b] = key
    out = []
    for i in range(q):
        a = data[2 + 2 * i]
        b = data[3 + 2 * i]
        if a == b:
            out.append('0')
            continue
        res = None
        out_a = best.get(a, {})
        if b in out_a:
            c, m = out_a[b]
            res = (c, 1, (m,))
        for mid, (c1, m1) in out_a.items():
            leg = best.get(mid, {}).get(b)
            if leg is not None:
                cand = (c1 + leg[0], 2, (m1, leg[1]))
                if res is None or cand < res:
                    res = cand
        if res is None:
            out.append('-1')
        else:
            out.append(str(res[0]) + ' ' + ' '.join(res[2]))
    print('\n'.join(out))

main()

